package dev.thefoolish.generated.createasimpleworkouttrackingapps;import android.text.InputType;import android.widget.*;public final class TimelineActivity extends AppScreen{private LinearLayout recent;protected void render(){body.addView(text("Workout",26,true));String[] exercises={"Squat","Bench Press","Deadlift","Push Up","Pull Up","Overhead Press","Barbell Row","Lunge","Plank"};Spinner exercise=new Spinner(this);ArrayAdapter<String> exerciseAdapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,exercises);exerciseAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);exercise.setAdapter(exerciseAdapter);EditText weight=field("Weight");EditText reps=field("Reps");weight.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);reps.setInputType(InputType.TYPE_CLASS_NUMBER);body.addView(exercise);body.addView(weight);body.addView(reps);Button save=button("Complete set");save.setOnClickListener(v->{String ex=String.valueOf(exercise.getSelectedItem());try{double w=Double.parseDouble(weight.getText().toString());int r=Integer.parseInt(reps.getText().toString());if(w<0||r<=0)throw new Exception();int gain=Math.max(5,(int)Math.round(r+Math.min(40,w/5)));store.number("workout_xp",store.number("workout_xp")+gain);store.number("stat_strength",store.number("stat_strength")+Math.max(1,(int)(w/25)));store.number("stat_endurance",store.number("stat_endurance")+Math.max(1,r/5));String old=store.text("workout_history","");store.putText("workout_history",ex+"|"+w+"|"+r+(old.isEmpty()?"":"\n"+old));weight.setText("");reps.setText("");save.setText("+"+gain+" XP");showRecent();}catch(Exception e){reps.setError("Enter valid weight and reps");}});body.addView(save);body.addView(text("Recent workouts",20,true));recent=new LinearLayout(this);recent.setOrientation(LinearLayout.VERTICAL);body.addView(recent);showRecent();}private void showRecent(){recent.removeAllViews();String history=store.text("workout_history","");if(history.isEmpty()){recent.addView(text("No workouts logged yet.",14,false));return;}for(String row:history.split("\n")){String[] x=row.split("[|]",3);if(x.length>=3)recent.addView(card(x[0],"Weight: "+x[1]+" · Reps: "+x[2]));}}}